INSERT INTO public.recipes (id, name, description, category, image_url, prep_minutes, cook_minutes, servings, tags, steps, deleted_at, created_at) VALUES (1, 'Chicken Adobo', 'The Philippines'' unofficial national dish: chicken braised in soy sauce, vinegar and garlic.', 'Main Dish', 'images/chicken-adobo.jpg', 15, 40, 4, ARRAY['chicken','filipino','rice','savory'], ARRAY['Combine chicken, soy sauce, vinegar, garlic, peppercorns and bay leaves. Marinate for 30 minutes.','Transfer everything to a pot, add water and bring to a boil without stirring.','Lower the heat, cover and simmer for 30-35 minutes until the chicken is tender.','Uncover and let the sauce reduce until slightly thick. Serve with hot rice.'], null, '2026-11-20 09:05:57.522819+00'), (2, 'Pork Sinigang', 'A sour and savory pork soup with vegetables, soured with tamarind.', 'Soup', 'images/pork-sinigang.jpg', 15, 60, 5, ARRAY['pork','soup','sour','filipino'], ARRAY['Boil the water with onion and tomatoes, then add the pork ribs.','Skim the scum and simmer for 45-60 minutes until the pork is tender.','Add the radish and the sinigang mix and cook for 5 minutes.','Add chilies and kangkong, season with fish sauce and serve hot.'], null, '2026-11-20 09:05:57.522819+00'), (3, 'Kinilaw na Tanigue', 'A Visayan ceviche: fresh fish cured in vinegar and calamansi with ginger and chili.', 'Appetizer', 'images/kinilaw.jpg', 20, 0, 4, ARRAY['fish','seafood','raw','visayan','cebu'], ARRAY['Wash the fish cubes briefly in vinegar and drain.','In a bowl, combine fish, fresh vinegar, calamansi juice, ginger, onion and chilies.','Season with salt and toss gently.','Chill for 10-15 minutes and serve immediately.'], null, '2026-11-20 09:05:57.522819+00'), (4, 'Lechon Kawali', 'Crispy deep-fried pork belly with crackling skin and juicy meat.', 'Main Dish', 'images/lechon-kawali.jpg', 20, 90, 6, ARRAY['pork','crispy','fried','filipino'], ARRAY['Boil pork with salt, peppercorns, bay leaves and garlic for 45 minutes until tender.','Drain and let it air-dry completely, ideally in the fridge for a few hours.','Heat oil to medium-high and carefully fry the pork until golden and blistered.','Rest briefly, chop into pieces and serve with liver sauce or spiced vinegar.'], null, '2026-11-20 09:05:57.522819+00'), (5, 'Pancit Canton', 'Stir-fried egg noodles with vegetables and meat, a staple at celebrations.', 'Noodles', 'images/pancit-canton.jpg', 15, 20, 4, ARRAY['noodles','chicken','vegetables','filipino','birthday'], ARRAY['Sauté garlic and chicken until cooked through.','Add carrot and cabbage, then pour in broth, soy sauce and oyster sauce.','Bring to a simmer, add the noodles and toss until the liquid is absorbed.','Serve with calamansi on the side.'], null, '2026-11-20 09:05:57.522819+00'), (6, 'Tinolang Manok', 'A comforting ginger chicken soup with green papaya and chili leaves.', 'Soup', 'images/tinola.jpg', 10, 35, 4, ARRAY['chicken','soup','ginger','filipino','healthy'], ARRAY['Sauté ginger and onion, then add chicken and fish sauce until lightly browned.','Pour in water and simmer for 25 minutes.','Add the green papaya and cook until tender.','Stir in chili leaves, cook for 1 minute and serve.'], null, '2026-11-20 09:05:57.522819+00'), (7, 'Leche Flan', 'A silky, rich caramel custard made with egg yolks and condensed milk.', 'Dessert', 'images/leche-flan.jpg', 20, 50, 8, ARRAY['dessert','sweet','egg','caramel','filipino'], ARRAY['Melt the sugar in a llanera (mold) until golden brown and swirl to coat the base.','Gently mix yolks, condensed milk, evaporated milk and vanilla. Strain the mixture.','Pour into the mold, cover tightly with foil.','Steam on low heat for 45-50 minutes. Cool, chill, then unmold and serve.'], null, '2026-11-20 09:05:57.522819+00'), (8, 'Spaghetti Carbonara', 'Classic Roman pasta with eggs, cheese, crispy bacon and black pepper.', 'Pasta', 'images/carbonara.jpg', 10, 15, 2, ARRAY['pasta','italian','bacon','egg','quick'], ARRAY['Cook spaghetti in salted water until al dente. Reserve some pasta water.','Fry the bacon until crisp, then turn off the heat.','Whisk eggs, parmesan and pepper in a bowl.','Toss hot pasta with bacon, then quickly stir in the egg mixture with splashes of pasta water until creamy.'], null, '2026-11-20 09:05:57.522819+00'), (9, 'Fluffy Pancakes', 'Thick, soft pancakes perfect with butter and maple syrup.', 'Breakfast', 'images/pancakes.jpg', 10, 15, 4, ARRAY['breakfast','sweet','egg','milk','quick'], ARRAY['Whisk flour, baking powder, sugar and a pinch of salt.','Add milk, egg and melted butter and mix until just combined (a few lumps are fine).','Pour 1/4 cup batter onto a lightly oiled pan over medium heat.','Flip when bubbles appear, cook until golden, and serve warm.'], null, '2026-11-20 09:05:57.522819+00');